import React from 'react';

function AboutUs() {
  return (
    <div className="about-us">
      <h2>About Paradise Nursery</h2>
      <p>
        Paradise Nursery was founded on a simple belief: every home deserves
        a little more green. We are a small team of plant lovers who source,
        grow, and hand-check every plant before it reaches your door.
      </p>
      <p>
        From air-purifying favorites to low-maintenance succulents and
        fragrant aromatic herbs, our collection is curated for beginners and
        seasoned plant parents alike. We believe healthy plants make for
        healthier, happier homes — and we're here to help you find the right
        ones for yours.
      </p>
    </div>
  );
}

export default AboutUs;
